import { createHmac, randomUUID, timingSafeEqual } from "node:crypto";
import { accountOrigins } from "./authConfig";
import { privateTrialStore, type TrialStore } from "./trialStore";

export const TRIAL_COOKIE_NAME = "__Host-nesalio_trial";
export const FREE_TRIAL_TURNS = 3;
export type TrialOperation = "tutor" | "voice" | "transcribe" | "feedback";
export type TrialAccess =
  | { ok: true; guestId: string; remaining: number; headers: Headers }
  | { ok: false; response: Response };
export interface TrialStatus { enabled: boolean; hasTrial: boolean; remaining: number; exhausted: boolean }

const DAY = 86_400_000;
const LIFETIME = 30 * DAY;
const PREFIX = "nesalio-trials/v1/";
const MAX_RETRIES = 8;
const VOICE_GRACE = 10 * 60_000;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const CAPS = {
  tutor: { guest: FREE_TRIAL_TURNS, ip: 60, global: 100 },
  voice: { guest: 48, ip: 960, global: 1600 },
  transcribe: { guest: 3, ip: 60, global: 100 },
  feedback: { guest: 4, ip: 12, global: 100 },
  initialize: { ip: 20, global: 100 },
} as const;

interface Identity { id: string; issued: number; expires: number }
interface Guest extends Identity {
  kind: "guest"; tutor: number; voice: number; transcribe: number; feedback: number; voiceUntil: number;
}
interface Counter { kind: "counter"; count: number }
type State = Guest | Counter;

class QuotaReached extends Error {}

function unavailable(): TrialAccess {
  return { ok: false, response: Response.json({ code: "trial_unavailable", error: "L’essai est temporairement indisponible. Connecte-toi pour continuer." }, {
    status: 503, headers: { "Cache-Control": "no-store", "Vary": "Cookie, Origin" },
  }) };
}

function exhausted(headers?: Headers): TrialAccess {
  const output = new Headers(headers);
  output.set("Cache-Control", "no-store");
  output.set("Vary", "Cookie, Origin");
  output.set("X-Nesalio-Account-Required", "1");
  return { ok: false, response: Response.json({ code: "trial_exhausted", error: "Crée ton compte gratuit pour continuer sans perdre ta séance." }, { status: 401, headers: output }) };
}

function isGuest(value: unknown): value is Guest {
  if (!value || typeof value !== "object") return false;
  const record = value as Partial<Guest>;
  return record.kind === "guest" && typeof record.id === "string" && UUID.test(record.id)
    && [record.issued, record.expires, record.voiceUntil, record.tutor, record.voice, record.transcribe, record.feedback]
      .every((n) => typeof n === "number" && Number.isSafeInteger(n) && n >= 0)
    && record.expires === record.issued! + LIFETIME;
}

function isCounter(value: unknown): value is Counter {
  if (!value || typeof value !== "object") return false;
  const record = value as Partial<Counter>;
  return record.kind === "counter" && typeof record.count === "number" && Number.isSafeInteger(record.count) && record.count >= 0;
}

/** Injectable storage makes concurrent requests testable without weakening production checks. */
export function createTrialService(options: { store?: TrialStore; env?: NodeJS.ProcessEnv; now?: () => number } = {}) {
  const store = options.store ?? privateTrialStore;
  const env = options.env ?? process.env;
  const clock = options.now ?? Date.now;
  const namespace = env.VERCEL_ENV === "production" ? "production" : env.VERCEL_ENV === "preview" ? "preview" : "development";
  const prefix = `${PREFIX}${namespace}/`;
  const secret = () => env.TRIAL_COOKIE_SECRET?.trim() ?? "";
  const enabled = () => Buffer.byteLength(secret(), "utf8") >= 32 && Boolean(env.BLOB_READ_WRITE_TOKEN?.trim());
  const mac = (value: string) => createHmac("sha256", secret()).update(value).digest("base64url");
  const guestPath = (identity: Identity) => `${prefix}guests/${new Date(identity.issued).toISOString().slice(0, 10)}/${identity.id}.json`;

  function parseIdentity(request: Request, now: number): Identity | null {
    const cookie = request.headers.get("cookie")?.split(";").map((part) => part.trim()).find((part) => part.startsWith(`${TRIAL_COOKIE_NAME}=`));
    if (!cookie) return null;
    const [version, id, issuedText, expiresText, signature, ...extra] = cookie.slice(TRIAL_COOKIE_NAME.length + 1).split(".");
    if (version !== "v1" || !id || !UUID.test(id) || !issuedText || !expiresText || !signature || extra.length) return null;
    if (!/^\d{13}$/.test(issuedText) || !/^\d{13}$/.test(expiresText) || !/^[A-Za-z0-9_-]{43}$/.test(signature)) return null;
    const issued = Number(issuedText), expires = Number(expiresText);
    if (issued > now || expires <= now || expires !== issued + LIFETIME) return null;
    const signed = `v1.${id}.${issuedText}.${expiresText}`;
    if (!timingSafeEqual(Buffer.from(signature), Buffer.from(mac(`cookie:${signed}`)))) return null;
    return { id, issued, expires };
  }

  function cookieHeader(identity: Identity): Headers {
    const data = `v1.${identity.id}.${identity.issued}.${identity.expires}`;
    return new Headers({
      "Set-Cookie": `${TRIAL_COOKIE_NAME}=${data}.${mac(`cookie:${data}`)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${LIFETIME / 1000}`,
      "Cache-Control": "no-store", "Vary": "Cookie, Origin",
    });
  }

  function originError(request: Request): TrialAccess | null {
    const origin = request.headers.get("origin");
    if (request.headers.get("sec-fetch-site") === "cross-site" || (origin !== null && !accountOrigins(env).includes(origin))) {
      return { ok: false, response: Response.json({ error: "Cette requête ne vient pas de Nesalio." }, { status: 403, headers: { "Cache-Control": "no-store" } }) };
    }
    return null;
  }

  async function update(path: string, validate: (value: unknown) => value is State, change: (current: State | null) => State): Promise<State> {
    for (let retry = 0; retry < MAX_RETRIES; retry++) {
      const entry = await store.read(path);
      if (entry && !validate(entry.value)) throw new Error("Invalid trial state");
      const next = change(entry ? entry.value as State : null);
      const saved = entry ? await store.replace(path, next, entry.etag) : await store.create(path, next);
      if (saved) return next;
    }
    throw new Error("Trial quota contention");
  }

  async function reserveDaily(request: Request, operation: TrialOperation | "initialize", now: number) {
    const day = new Date(now).toISOString().slice(0, 10);
    // Vercel supplies the trusted forwarding header. HMAC, not a plain IP hash,
    // prevents offline recovery of addresses; rotate the pseudonym every UTC day.
    const forwarded = env.VERCEL
      ? request.headers.get("x-vercel-forwarded-for")
      : request.headers.get("x-forwarded-for");
    const address = forwarded?.split(",")[0]?.trim() || "unknown";
    const ip = mac(`ip:${namespace}:${day}:${address}`);
    // Global first: after its cap, rotated/spoofed client identities cannot
    // create unbounded per-IP quota files. Partial failures may spend a slot.
    for (const [scope, cap] of [["global", CAPS[operation].global], [`ip/${ip}`, CAPS[operation].ip]] as const) {
      const path = `${prefix}daily/${day}/${operation}/${scope}.json`;
      await update(path, isCounter, (state) => {
        const count = (state as Counter | null)?.count ?? 0;
        if (count >= cap) throw new QuotaReached();
        return { kind: "counter", count: count + 1 };
      });
    }
  }

  async function existingGuest(identity: Identity): Promise<Guest | null> {
    const entry = await store.read(guestPath(identity));
    if (!entry) return null;
    if (!isGuest(entry.value) || entry.value.id !== identity.id || entry.value.issued !== identity.issued || entry.value.expires !== identity.expires) throw new Error("Invalid trial identity");
    return entry.value;
  }

  async function identify(request: Request, now: number, create: boolean): Promise<{ guest: Guest; headers: Headers } | null> {
    const identity = parseIdentity(request, now);
    if (identity) {
      const guest = await existingGuest(identity);
      // Never recreate a consumed/deleted durable record from a valid old cookie.
      return guest ? { guest, headers: new Headers() } : null;
    }
    if (!create) return null;
    await reserveDaily(request, "initialize", now);
    const guest: Guest = { kind: "guest", id: randomUUID(), issued: now, expires: now + LIFETIME, tutor: 0, voice: 0, transcribe: 0, feedback: 0, voiceUntil: 0 };
    if (!await store.create(guestPath(guest), guest)) throw new Error("Trial creation collision");
    return { guest, headers: cookieHeader(guest) };
  }

  async function initializeTrial(request: Request): Promise<TrialAccess> {
    const forbidden = originError(request);
    if (forbidden) return forbidden;
    if (!enabled()) return unavailable();
    try {
      const found = await identify(request, clock(), true);
      return found ? { ok: true, guestId: found.guest.id, remaining: Math.max(0, FREE_TRIAL_TURNS - found.guest.tutor), headers: found.headers } : exhausted();
    } catch (error) {
      return error instanceof QuotaReached ? exhausted() : unavailable();
    }
  }

  async function authorizeTrial(request: Request, operation: TrialOperation): Promise<TrialAccess> {
    const forbidden = originError(request);
    if (forbidden) return forbidden;
    if (!enabled()) return unavailable();
    let headers = new Headers();
    try {
      const now = clock();
      const found = await identify(request, now, operation === "tutor" || operation === "transcribe");
      if (!found) return exhausted();
      headers = found.headers;
      const allowed = (guest: Guest) => guest.expires > now && guest[operation] < CAPS[operation].guest
        && (operation === "voice" ? guest.tutor > 0 && guest.voiceUntil > now : operation === "feedback" || guest.tutor < FREE_TRIAL_TURNS);
      if (!allowed(found.guest)) return exhausted(headers);
      // Separate durable reservations deliberately never refund on partial
      // failure: an outage may overcount, but cannot grant extra paid operations.
      await reserveDaily(request, operation, now);
      const next = await update(guestPath(found.guest), isGuest, (state) => {
        if (!state || !isGuest(state) || !allowed(state)) throw new QuotaReached();
        return { ...state, [operation]: state[operation] + 1, ...(operation === "tutor" ? { voiceUntil: now + VOICE_GRACE } : {}) };
      }) as Guest;
      return { ok: true, guestId: next.id, remaining: Math.max(0, FREE_TRIAL_TURNS - next.tutor), headers };
    } catch (error) {
      return error instanceof QuotaReached ? exhausted(headers) : unavailable();
    }
  }

  async function getTrialStatus(request: Request): Promise<TrialStatus> {
    if (!enabled()) return { enabled: false, hasTrial: false, remaining: 0, exhausted: true };
    try {
      const identity = parseIdentity(request, clock());
      if (!identity) return { enabled: true, hasTrial: false, remaining: FREE_TRIAL_TURNS, exhausted: false };
      const guest = await existingGuest(identity);
      const remaining = guest ? Math.max(0, FREE_TRIAL_TURNS - guest.tutor) : 0;
      return { enabled: true, hasTrial: true, remaining, exhausted: remaining === 0 };
    } catch { return { enabled: false, hasTrial: false, remaining: 0, exhausted: true }; }
  }

  async function purgeExpiredTrials(now: Date = new Date(clock())): Promise<number> {
    if (!env.BLOB_READ_WRITE_TOKEN) return 0;
    const guests = await store.removeOlder(`${prefix}guests/`, new Date(now.getTime() - 31 * DAY));
    const daily = await store.removeOlder(`${prefix}daily/`, new Date(now.getTime() - 7 * DAY));
    return guests + daily;
  }

  return { initializeTrial, authorizeTrial, getTrialStatus, purgeExpiredTrials };
}

const trialService = createTrialService();
export const initializeTrial = trialService.initializeTrial;
export const authorizeTrial = trialService.authorizeTrial;
export const getTrialStatus = trialService.getTrialStatus;
export const purgeExpiredTrials = trialService.purgeExpiredTrials;

import { BlobPreconditionFailedError, del, get, list, put } from "@vercel/blob";

export interface TrialEntry { etag: string; value: unknown }
export interface TrialStore {
  read(path: string): Promise<TrialEntry | null>;
  create(path: string, value: unknown): Promise<boolean>;
  replace(path: string, value: unknown, etag: string): Promise<boolean>;
  removeOlder(prefix: string, before: Date): Promise<number>;
}

/** Private, durable and fail-closed. Never use the best-effort transcript store for access decisions. */
export const privateTrialStore: TrialStore = {
  async read(path) {
    const result = await get(path, { access: "private", useCache: false });
    if (!result) return null;
    if (result.statusCode !== 200 || !result.stream) throw new Error("Trial quota read unavailable");
    return { etag: result.blob.etag, value: JSON.parse(await new Response(result.stream).text()) as unknown };
  },
  async create(path, value) {
    try {
      await put(path, JSON.stringify(value), {
        access: "private", addRandomSuffix: false, allowOverwrite: false,
        contentType: "application/json", cacheControlMaxAge: 60,
      });
      return true;
    } catch (error) {
      // The SDK does not expose a dedicated AlreadyExists class. Confirm the
      // existing record with a strong read; all other failures remain failures.
      const existing = await this.read(path);
      if (existing) return false;
      throw error;
    }
  },
  async replace(path, value, etag) {
    try {
      await put(path, JSON.stringify(value), {
        access: "private", addRandomSuffix: false, allowOverwrite: true, ifMatch: etag,
        contentType: "application/json", cacheControlMaxAge: 60,
      });
      return true;
    } catch (error) {
      if (error instanceof BlobPreconditionFailedError) return false;
      throw error;
    }
  },
  async removeOlder(prefix, before) {
    let cursor: string | undefined;
    let removed = 0;
    do {
      const page = await list({ prefix, cursor, limit: 1000 });
      const expired = page.blobs.filter((blob) => new Date(blob.uploadedAt) < before).map((blob) => blob.pathname);
      for (let i = 0; i < expired.length; i += 500) await del(expired.slice(i, i + 500));
      removed += expired.length;
      cursor = page.hasMore ? page.cursor : undefined;
    } while (cursor);
    return removed;
  },
};

import { describe, expect, it } from "vitest";
import { createTrialService, TRIAL_COOKIE_NAME, type TrialAccess } from "./trial";
import type { TrialEntry, TrialStore } from "./trialStore";

class MemoryStore implements TrialStore {
  entries = new Map<string, TrialEntry>();
  writes = 0;
  removals: Array<{ prefix: string; before: Date }> = [];
  async read(path: string) { return structuredClone(this.entries.get(path) ?? null); }
  async create(path: string, value: unknown) {
    if (this.entries.has(path)) return false;
    this.entries.set(path, { etag: String(++this.writes), value: structuredClone(value) });
    return true;
  }
  async replace(path: string, value: unknown, etag: string) {
    if (this.entries.get(path)?.etag !== etag) return false;
    this.entries.set(path, { etag: String(++this.writes), value: structuredClone(value) });
    return true;
  }
  async removeOlder(prefix: string, before: Date) {
    this.removals.push({ prefix, before });
    return 0;
  }
}

const baseline = Date.UTC(2026, 10, 4, 18);
const env = (): NodeJS.ProcessEnv => ({
  TRIAL_COOKIE_SECRET: "a-dedicated-long-test-secret-at-least-32-bytes",
  BLOB_READ_WRITE_TOKEN: "a-private-storage-token", VERCEL: "1", VERCEL_ENV: "production",
  NODE_ENV: "production", NEXT_PUBLIC_APP_URL: "https://app.nesalio.com",
});
const request = (cookie?: string, ip = "198.51.100.42", more: Record<string, string> = {}) => new Request("https://app.nesalio.com/api/tutor", {
  method: "POST", headers: { origin: "https://app.nesalio.com", "x-vercel-forwarded-for": ip, ...(cookie ? { cookie } : {}), ...more },
});
function cookieOf(result: TrialAccess): string {
  if (!result.ok) throw new Error(`Trial denied: ${result.response.status}`);
  const cookie = result.headers.get("set-cookie");
  if (!cookie) throw new Error("No trial cookie");
  return cookie.split(";")[0]!;
}
function fixture() {
  const store = new MemoryStore();
  const configuration = env();
  let now = baseline;
  const service = createTrialService({ store, env: configuration, now: () => now });
  return { store, configuration, service, advance: (milliseconds: number) => { now += milliseconds; } };
}

describe("durable anonymous trial", () => {
  it("reads a fresh status without allocating a cookie, quota or record", async () => {
    const { store, service } = fixture();
    expect(await service.getTrialStatus(request())).toEqual({ enabled: true, hasTrial: false, remaining: 3, exhausted: false });
    expect(store.entries.size).toBe(0);
    expect(store.writes).toBe(0);
  });

  it("initializes a signed host-only cookie without consuming a tutor turn", async () => {
    const { service } = fixture();
    const initialized = await service.initializeTrial(request());
    expect(initialized.ok).toBe(true);
    if (!initialized.ok) return;
    expect(initialized.remaining).toBe(3);
    const header = initialized.headers.get("set-cookie")!;
    expect(header).toContain(`${TRIAL_COOKIE_NAME}=v1.`);
    expect(header).toContain("Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000");
    expect(header).not.toContain("Domain=");
    expect(await service.getTrialStatus(request(cookieOf(initialized)))).toEqual({ enabled: true, hasTrial: true, remaining: 3, exhausted: false });
  });

  it("automatically initializes the first tutor call and permits exactly three reservations", async () => {
    const { service } = fixture();
    const first = await service.authorizeTrial(request(), "tutor");
    const cookie = cookieOf(first);
    expect(first.ok && first.remaining).toBe(2);
    expect((await service.authorizeTrial(request(cookie), "tutor")).ok).toBe(true);
    const third = await service.authorizeTrial(request(cookie), "tutor");
    expect(third.ok && third.remaining).toBe(0);
    const denied = await service.authorizeTrial(request(cookie), "tutor");
    expect(denied.ok).toBe(false);
    if (!denied.ok) {
      expect(denied.response.status).toBe(401);
      expect(denied.response.headers.get("x-nesalio-account-required")).toBe("1");
      expect(denied.response.headers.get("cache-control")).toBe("no-store");
      expect(await denied.response.json()).toMatchObject({ code: "trial_exhausted" });
    }
  });

  it("shares the quota across service instances and rejects concurrent replay beyond three turns", async () => {
    const { service, store, configuration } = fixture();
    const cookie = cookieOf(await service.initializeTrial(request()));
    const another = createTrialService({ store, env: configuration, now: () => baseline });
    const results = await Promise.all(Array.from({ length: 12 }, (_, index) => (index % 2 ? another : service).authorizeTrial(request(cookie), "tutor")));
    expect(results.filter((result) => result.ok)).toHaveLength(3);
    expect((await another.getTrialStatus(request(cookie))).remaining).toBe(0);
  });

  it("does not refund a reserved turn when downstream processing fails or a client retries", async () => {
    const { service } = fixture();
    const first = await service.authorizeTrial(request(), "tutor");
    const cookie = cookieOf(first);
    // The caller has not reported any success. Paid reservations still count.
    expect((await service.getTrialStatus(request(cookie))).remaining).toBe(2);
    await service.authorizeTrial(request(cookie), "tutor");
    expect((await service.getTrialStatus(request(cookie))).remaining).toBe(1);
  });

  it("bounds microphone calls before the initial question without granting unlimited voice calls", async () => {
    const { service } = fixture();
    const transcribed = await service.authorizeTrial(request(), "transcribe");
    const cookie = cookieOf(transcribed);
    expect(transcribed.ok && transcribed.remaining).toBe(3);
    expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(false);
    await service.authorizeTrial(request(cookie), "transcribe");
    await service.authorizeTrial(request(cookie), "transcribe");
    expect((await service.authorizeTrial(request(cookie), "transcribe")).ok).toBe(false);
    expect((await service.getTrialStatus(request(cookie))).remaining).toBe(3);
  });

  it("allows bounded audio for the third response then expires its short playback grace", async () => {
    const { service, advance } = fixture();
    const cookie = cookieOf(await service.authorizeTrial(request(), "tutor"));
    await service.authorizeTrial(request(cookie), "tutor");
    await service.authorizeTrial(request(cookie), "tutor");
    expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(true);
    expect((await service.authorizeTrial(request(cookie), "transcribe")).ok).toBe(false);
    advance(10 * 60_000 + 1);
    expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(false);
  });

  it("permits only 48 voice calls per trial even during the playback grace", async () => {
    const { service } = fixture();
    const cookie = cookieOf(await service.authorizeTrial(request(), "tutor"));
    for (let i = 0; i < 48; i++) expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(true);
    expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(false);
    expect((await service.authorizeTrial(request(), "voice")).ok).toBe(false);
  });

  it("allows four feedback submissions with an issued cookie after the third response", async () => {
    const { service } = fixture();
    expect((await service.authorizeTrial(request(), "feedback")).ok).toBe(false);
    const cookie = cookieOf(await service.authorizeTrial(request(), "tutor"));
    await service.authorizeTrial(request(cookie), "tutor");
    await service.authorizeTrial(request(cookie), "tutor");
    for (let i = 0; i < 4; i++) expect((await service.authorizeTrial(request(cookie), "feedback")).ok).toBe(true);
    expect((await service.authorizeTrial(request(cookie), "feedback")).ok).toBe(false);
  });

  it("limits cookie clearing on the same platform-provided IP and stores no raw IP", async () => {
    const { service, store } = fixture();
    for (let i = 0; i < 20; i++) {
      const cookie = cookieOf(await service.initializeTrial(request()));
      for (let j = 0; j < 3; j++) expect((await service.authorizeTrial(request(cookie), "tutor")).ok).toBe(true);
    }
    expect((await service.initializeTrial(request())).ok).toBe(false);
    expect(JSON.stringify([...store.entries])).not.toContain("198.51.100.42");
  });

  it("ignores client spoofed forwarding headers on Vercel and shares the unknown-IP bucket", async () => {
    const { service } = fixture();
    for (let i = 0; i < 20; i++) {
      const input = request(undefined, "", { "x-forwarded-for": `203.0.113.${i}`, "x-real-ip": `203.0.113.${i}` });
      expect((await service.initializeTrial(input)).ok).toBe(true);
    }
    expect((await service.initializeTrial(request(undefined, "", { "x-forwarded-for": "192.0.2.234" }))).ok).toBe(false);
  });

  it("enforces a global daily limit of 100 tutor requests despite distinct IPs and cookies", async () => {
    const { service } = fixture();
    let allowed = 0;
    for (let i = 0; i < 35; i++) {
      const ip = `203.0.113.${i}`;
      const cookie = cookieOf(await service.initializeTrial(request(undefined, ip)));
      for (let j = 0; j < 3; j++) if ((await service.authorizeTrial(request(cookie, ip), "tutor")).ok) allowed++;
    }
    expect(allowed).toBe(100);
  });

  it("separates preview and production quotas even when the store and signing key are shared", async () => {
    const { service, store, configuration } = fixture();
    const cookie = cookieOf(await service.authorizeTrial(request(), "tutor"));
    const preview = createTrialService({ store, env: { ...configuration, VERCEL_ENV: "preview" }, now: () => baseline });
    expect((await preview.authorizeTrial(request(cookie), "tutor")).ok).toBe(false);
    const previewCookie = cookieOf(await preview.authorizeTrial(request(), "tutor"));
    expect((await preview.getTrialStatus(request(previewCookie))).remaining).toBe(2);
    expect((await service.getTrialStatus(request(cookie))).remaining).toBe(2);
    expect([...store.entries.keys()].some((path) => path.includes("/preview/"))).toBe(true);
    expect([...store.entries.keys()].some((path) => path.includes("/production/"))).toBe(true);
  });

  it("rejects foreign origins before performing storage operations", async () => {
    const { service, store } = fixture();
    const result = await service.authorizeTrial(request(undefined, "198.51.100.42", { origin: "https://evil.example" }), "tutor");
    expect(result.ok).toBe(false);
    if (!result.ok) expect(result.response.status).toBe(403);
    expect(store.writes).toBe(0);
  });

  it("fails closed on short/missing configuration and storage errors, ignoring RECORD_SESSIONS", async () => {
    const { service, configuration, store } = fixture();
    configuration.RECORD_SESSIONS = "0";
    expect((await service.initializeTrial(request())).ok).toBe(true);
    configuration.TRIAL_COOKIE_SECRET = "short";
    const missing = await service.authorizeTrial(request(), "tutor");
    expect(missing.ok).toBe(false);
    if (!missing.ok) expect(missing.response.status).toBe(503);
    configuration.TRIAL_COOKIE_SECRET = env().TRIAL_COOKIE_SECRET;
    store.read = async () => { throw new Error("storage outage with sensitive detail"); };
    const broken = await service.authorizeTrial(request(), "tutor");
    expect(broken.ok).toBe(false);
    if (!broken.ok) {
      expect(broken.response.status).toBe(503);
      expect(await broken.response.text()).not.toContain("sensitive detail");
    }
  });

  it("expires guest identity after 30 days and never recreates a deleted durable identity", async () => {
    const { service, store, advance } = fixture();
    const cookie = cookieOf(await service.initializeTrial(request()));
    const path = [...store.entries.keys()].find((key) => key.includes("/guests/"))!;
    store.entries.delete(path);
    expect((await service.authorizeTrial(request(cookie), "tutor")).ok).toBe(false);
    expect(store.entries.has(path)).toBe(false);
    advance(31 * 86_400_000);
    expect((await service.authorizeTrial(request(cookie), "voice")).ok).toBe(false);
  });

  it("rejects corrupt durable records and bounded compare-and-swap contention", async () => {
    const { service, store } = fixture();
    const cookie = cookieOf(await service.initializeTrial(request()));
    const path = [...store.entries.keys()].find((key) => key.includes("/guests/"))!;
    store.entries.get(path)!.value = { kind: "guest", tutor: -9000 };
    const corrupt = await service.authorizeTrial(request(cookie), "tutor");
    expect(corrupt.ok).toBe(false);
    if (!corrupt.ok) expect(corrupt.response.status).toBe(503);
    const other = fixture();
    other.store.replace = async () => false;
    const first = await other.service.initializeTrial(request());
    expect(first.ok).toBe(true);
    const busy = await other.service.authorizeTrial(request(cookieOf(first)), "tutor");
    expect(busy.ok).toBe(false);
    if (!busy.ok) expect(busy.response.status).toBe(503);
  });

  it("keeps quota cleanup separate from transcript retention and limited to its namespace", async () => {
    const { service, store } = fixture();
    await service.purgeExpiredTrials(new Date(baseline));
    expect(store.removals).toEqual([
      { prefix: "nesalio-trials/v1/production/guests/", before: new Date(baseline - 31 * 86_400_000) },
      { prefix: "nesalio-trials/v1/production/daily/", before: new Date(baseline - 7 * 86_400_000) },
    ]);
  });
});

