import { identifyUsage } from "@/server/usageAccess";
import { getTrialStatus, initializeTrial } from "@/server/trial";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const headers = { "Cache-Control": "no-store", "Vary": "Cookie, Origin" };

export async function GET(request: Request): Promise<Response> {
  const identity = await identifyUsage(request);
  if (!identity.ok) return identity.response;
  if (identity.userId) return Response.json({ authenticated: true, remaining: null, limit: 3 }, { headers });
  try {
    return Response.json({ authenticated: false, limit: 3, ...await getTrialStatus(request) }, { headers });
  } catch {
    return Response.json({ error: "L'essai est temporairement indisponible. Réessaie dans un instant." }, { status: 503, headers });
  }
}

export async function POST(request: Request): Promise<Response> {
  const identity = await identifyUsage(request);
  if (!identity.ok) return identity.response;
  if (identity.userId) return Response.json({ authenticated: true, remaining: null, limit: 3 }, { headers });
  const trial = await initializeTrial(request);
  if (!trial.ok) return trial.response;
  const resultHeaders = new Headers(headers);
  for (const [key, value] of trial.headers) resultHeaders.set(key, value);
  return Response.json({ authenticated: false, remaining: trial.remaining, limit: 3 }, { headers: resultHeaders });
}

/**
 * POST /api/tutor — reçoit la question de l'élève et renvoie l'explication
 * en flux NDJSON (un événement par ligne), au fur et à mesure que le modèle
 * la génère. Les identifiants du modèle ne quittent jamais le serveur.
 * Le tour est enregistré pour améliorer l'outil (domain/sessionLog.ts).
 */
import type { StreamEvent } from "@/domain/scene/schema";
import { encodeLine } from "@/domain/tutor/ndjson";
import { TutorRequestSchema } from "@/domain/tutor/request";
import { readAiConfig } from "@/server/config";
import { createSessionLimits } from "@/server/rateLimit";
import { refFromHeaders, shortSession } from "@/domain/session";
import { streamChatCompletion } from "@/server/tutor/chatCompletions";
import { tutorEvents } from "@/server/tutor/service";
import { after } from "next/server";
import { createTurnRecorder } from "@/domain/sessionLog";
import { recordEnv, saveTurn } from "@/server/sessionStore";
import { withRecording } from "@/server/tutor/recording";
import { readBoundedText } from "@/server/http";
import { identifyUsage, reserveUsage, usageResponse } from "@/server/usageAccess";

export const runtime = "nodejs";
// Un tour où le modèle réfléchit longtemps dépasse parfois 60 s : coupé, il finissait sans question.
export const maxDuration = 180;

// Le corps inclut le contexte borné de la séance.
const MAX_BODY_BYTES = 96_000;
// Par compte vérifié : une séance compte plusieurs tours (un appel par réponse de l'élève),
// soit environ 8 séances par 10 minutes ; une même adresse (une classe) peut en ouvrir 12 fois plus.
const limiter = createSessionLimits({ limit: 40, windowMs: 10 * 60_000 });

const NDJSON_HEADERS = {
  "Content-Type": "application/x-ndjson; charset=utf-8",
  "Cache-Control": "no-store",
  "X-Accel-Buffering": "no",
};

function single(event: StreamEvent, status: number, extra: Record<string, string> = {}) {
  return new Response(encodeLine(event), { status, headers: { ...NDJSON_HEADERS, ...extra } });
}

export async function POST(request: Request): Promise<Response> {
  const access = await identifyUsage(request, true);
  if (!access.ok) return access.response;
  // Limiter aussi les requêtes invalides avant leur lecture et leur validation.
  const limit = limiter.check(request.headers, undefined, access.userId);
  const tag = limit.session ? `[session ${shortSession(limit.session)}]` : "[sans session]";
  if (!limit.allowed) {
    return single(
      { kind: "error", code: "rate_limited", message: "Tu as posé beaucoup de questions d'un coup. Réessaie dans quelques minutes." },
      429,
      { "Retry-After": String(limit.retryAfterSeconds) },
    );
  }

  const raw = await readBoundedText(request, MAX_BODY_BYTES);
  if (!raw.ok) return single({ kind: "error", code: "bad_request", message: raw.status === 413 ? "Question trop longue." : "Requête illisible." }, raw.status);
  let body: unknown;
  try { body = JSON.parse(raw.text); }
  catch { return single({ kind: "error", code: "bad_request", message: "Requête illisible." }, 400); }
  const parsed = TutorRequestSchema.safeParse(body);
  if (!parsed.success) return single({ kind: "error", code: "bad_request", message: "Requête invalide." }, 400);

  const permit = await reserveUsage(request, access, "tutor", true);
  if (!permit.ok) return permit.response;

  const config = readAiConfig(request.headers);
  // Chaque tour est enregistré (sans nom, IP ni audio) pour améliorer Nesalio ; écrit après la réponse.
  const recorder = createTurnRecorder({
    request: parsed.data,
    session: limit.session,
    ref: refFromHeaders(request.headers),
    env: recordEnv(),
    source: config.chat ? "model" : "demo",
    model: config.chat?.model,
    startedAt: new Date(),
    clock: { now: () => Date.now() },
  });
  after(() => saveTurn(recorder.record()));
  const events = withRecording(
    tutorEvents(parsed.data, {
      provider: config.chat,
      completion: streamChatCompletion,
      signal: request.signal,
      log: (message, detail) => console.warn(tag, message, detail),
    }),
    recorder,
  );

  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        const { value, done } = await events.next();
        if (done) controller.close();
        else controller.enqueue(encoder.encode(encodeLine(value)));
      } catch (error) {
        console.error(tag, "tutor: flux interrompu", error);
        controller.close();
      }
    },
    async cancel() {
      await events.return(undefined);
    },
  });

  return usageResponse(new Response(stream, { status: 200, headers: NDJSON_HEADERS }), permit);
}

/**
 * POST /api/voice — la voix de Nesa : { text } → audio (WAV ou MP3), avec la
 * partie vraiment parlée dans l'en-tête X-Speech-Span (« début,fin » en ms).
 * Réponse 503 si aucune voix n'est configurée : le navigateur se rabat alors
 * sur sa propre synthèse vocale.
 */
import { z } from "zod";
import { speechSpanOf, synthesizeSpeech } from "@/server/ai/audio";
import { readAiConfig } from "@/server/config";
import { checkRate, jsonError, readJson } from "@/server/http";
import { createSessionLimits } from "@/server/rateLimit";
import { isUnavailable } from "@/server/tutor/service";
import { SPEECH_SPAN_HEADER } from "@/domain/audio/speechSpan";
import { identifyUsage, reserveUsage, usageResponse } from "@/server/usageAccess";

export const runtime = "nodejs";
export const maxDuration = 30;

const Body = z.object({ text: z.string().trim().min(1).max(400) });
// Une séance compte une dizaine de phrases : la limite est large mais réelle.
const limiter = createSessionLimits({ limit: 160, windowMs: 10 * 60_000 });

export async function POST(request: Request): Promise<Response> {
  const access = await identifyUsage(request);
  if (!access.ok) return access.response;
  const limited = checkRate(limiter, request, access.userId);
  if (limited) return limited;
  const read = await readJson(request, 4_000);
  if (!read.ok) return read.response;
  const parsed = Body.safeParse(read.body);
  if (!parsed.success) return jsonError(400, "Texte invalide.");

  const config = readAiConfig(request.headers);
  if (!config.gatewayToken) return jsonError(503, "Voix non configurée.");

  const permit = await reserveUsage(request, access, "voice");
  if (!permit.ok) return permit.response;

  try {
    const { audio, mediaType } = await synthesizeSpeech({
      token: config.gatewayToken,
      model: config.voice.model,
      voice: config.voice.voice,
      instructions: config.voice.instructions,
      text: parsed.data.text,
      signal: request.signal,
    });
    // Partie vraiment parlée (sans les silences du début et de la fin) : le lecteur y cale les repères {id}.
    const span = speechSpanOf(audio, mediaType);
    return usageResponse(new Response(audio as unknown as BodyInit, {
      headers: {
        "Content-Type": mediaType,
        "Cache-Control": "private, max-age=3600",
        ...(span ? { [SPEECH_SPAN_HEADER]: `${span.startMs},${span.endMs}` } : {}),
      },
    }), permit);
  } catch (error) {
    console.warn("voice: échec de la synthèse", error);
    // 503 : le navigateur passe tout de suite à sa propre voix.
    if (isUnavailable(error)) return usageResponse(jsonError(503, "Voix indisponible pour le moment."), permit);
    return usageResponse(jsonError(502, "La voix n'a pas pu être générée."), permit);
  }
}

/**
 * POST /api/feedback — un testeur signale un problème ou donne une idée.
 *
 * Le retour est transmis au même formulaire Formspree que les inscriptions du
 * site (champ « etape » = « retour-outil », pour les trier), ou à
 * FEEDBACK_ENDPOINT s'il est défini. Rien n'est conservé par l'application.
 */
import { refFromHeaders, shortSession } from "@/domain/session";
import { FEEDBACK_LABELS, FeedbackSchema } from "@/domain/feedback";
import { jsonError, readJson } from "@/server/http";
import { forwardToForm } from "@/server/forms";
import { createSessionLimits } from "@/server/rateLimit";
import { identifyUsage, reserveUsage, usageResponse } from "@/server/usageAccess";

export const runtime = "nodejs";

// Assez pour signaler plusieurs problèmes pendant un essai, pas assez pour inonder le formulaire.
const limiter = createSessionLimits({ limit: 8, windowMs: 30 * 60_000, ipFactor: 6 });

export async function POST(request: Request): Promise<Response> {
  const access = await identifyUsage(request);
  if (!access.ok) return access.response;
  const read = await readJson(request, 40_000);
  if (!read.ok) return read.response;
  const parsed = FeedbackSchema.safeParse(read.body);
  if (!parsed.success) return jsonError(400, parsed.error.issues[0]?.message ?? "Retour invalide.");

  const limit = limiter.check(request.headers, undefined, access.userId);
  if (!limit.allowed) return jsonError(429, "Merci ! Tu as déjà envoyé plusieurs retours ; réessaie un peu plus tard.");

  const permit = await reserveUsage(request, access, "feedback");
  if (!permit.ok) return permit.response;

  const { kind, message, email, context } = parsed.data;
  const payload = {
    etape: "retour-outil",
    _subject: `Nesalio · retour de testeur : ${FEEDBACK_LABELS[kind]}`,
    type: FEEDBACK_LABELS[kind],
    message,
    ...(email ? { email } : {}),
    session: limit.session ? shortSession(limit.session) : "inconnue",
    ref: refFromHeaders(request.headers) ?? "sans inscription",
    ...(context
      ? {
          question: context.question ?? "",
          seance: context.title ?? "",
          etat: context.status,
          dernieres_phrases: context.recent.join("\n"),
          tableau: context.board.join("\n"),
          ecran: context.screen,
          navigateur: context.browser,
          rejeu: context.replay ?? "",
        }
      : { contexte: "non joint" }),
  };

  if (!(await forwardToForm(payload))) return usageResponse(jsonError(502, "L'envoi n'a pas fonctionné. Réessaie dans un instant."), permit);
  return usageResponse(Response.json({ ok: true }, { headers: { "Cache-Control": "no-store" } }), permit);
}

/**
 * POST /api/apres-essai — réponses aux questions posées après un premier essai.
 * Transmises au formulaire du site avec etape = « 3-apres-essai » et la
 * référence de l'inscription (ref), pour les relier aux réponses d'avant l'essai.
 */
import { AfterTrialSchema } from "@/domain/afterTrial";
import { refFromHeaders, shortSession } from "@/domain/session";
import { forwardToForm } from "@/server/forms";
import { jsonError, readJson } from "@/server/http";
import { createSessionLimits } from "@/server/rateLimit";
import { identifyUsage, reserveUsage, usageResponse } from "@/server/usageAccess";

export const runtime = "nodejs";

const limiter = createSessionLimits({ limit: 3, windowMs: 60 * 60_000, ipFactor: 10 });

export async function POST(request: Request): Promise<Response> {
  const access = await identifyUsage(request);
  if (!access.ok) return access.response;
  const read = await readJson(request, 8_000);
  if (!read.ok) return read.response;
  const parsed = AfterTrialSchema.safeParse(read.body);
  if (!parsed.success) return jsonError(400, "Réponses invalides.");
  const limit = limiter.check(request.headers, undefined, access.userId);
  if (!limit.allowed) return jsonError(429, "Merci, tes réponses sont déjà arrivées.");

  const permit = await reserveUsage(request, access, "feedback");
  if (!permit.ok) return permit.response;

  const a = parsed.data;
  const ok = await forwardToForm({
    etape: "3-apres-essai",
    _subject: "Nesalio · réponses après essai",
    ref: a.ref ?? refFromHeaders(request.headers) ?? "sans inscription",
    aurait_aide: a.helped,
    pourquoi: a.why ?? "",
    plus_utile: a.useful?.length ? a.useful.join(" · ") : "non répondu",
    ce_qui_manque: a.missing ?? "",
    derniere_fois: a.whatYouDid ?? "",
    depense_mensuelle: a.spending ?? "non répondu",
    urgence: a.urgency ?? "non répondu",
    question_posee: a.question ?? "",
    session: limit.session ? shortSession(limit.session) : "inconnue",
  });
  return usageResponse(ok ? Response.json({ ok: true }, { headers: { "Cache-Control": "no-store" } }) : jsonError(502, "L'envoi n'a pas fonctionné. Réessaie dans un instant."), permit);
}

/**
 * GET /api/seances/purge — appelé chaque jour par la tâche planifiée de Vercel
 * (vercel.json) : supprime les séances enregistrées depuis plus de 12 mois,
 * comme l'annonce la politique de confidentialité. Vercel envoie
 * « Authorization: Bearer <CRON_SECRET> » ; sans lui, 404.
 */
import { purgeOld } from "@/server/sessionStore";
import { purgeExpiredTrials } from "@/server/trial";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 60;

export async function GET(request: Request): Promise<Response> {
  const secret = process.env.CRON_SECRET?.trim();
  if (!secret || request.headers.get("authorization") !== `Bearer ${secret}`) return new Response("Not found", { status: 404 });
  const deleted = await purgeOld(new Date());
  const expiredTrials = await purgeExpiredTrials(new Date());
  return Response.json({ deleted, expiredTrials }, { headers: { "Cache-Control": "no-store" } });
}

/** Client-only notifications. The server remains the authority for trial access. */
export const TRIAL_UPDATED = "nesalio:trial-updated";
export const ACCOUNT_REQUIRED = "nesalio:account-required";
export const ACCOUNT_READY = "nesalio:account-ready";
export const ACCOUNT_CANCELLED = "nesalio:account-cancelled";

export function updateTrialFromResponse(response: Response): void {
  const raw = response.headers.get("X-Nesalio-Trial-Remaining");
  if (raw === null || raw.trim() === "" || typeof window === "undefined") return;
  const remaining = Number(raw);
  if (Number.isInteger(remaining) && remaining >= 0 && remaining <= 3) {
    window.dispatchEvent(new CustomEvent(TRIAL_UPDATED, { detail: { remaining } }));
  }
}

export function requestAccount(pendingRequest = false): void {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ACCOUNT_REQUIRED, { detail: { pendingRequest } }));
  }
}

/** Suspend the already requested turn. Only an explicit continue action resumes it. */
export function waitForAccount(signal: AbortSignal): Promise<boolean> {
  if (signal.aborted || typeof window === "undefined") return Promise.resolve(false);
  return new Promise((resolve) => {
    const finish = (allowed: boolean) => {
      signal.removeEventListener("abort", cancel);
      window.removeEventListener(ACCOUNT_READY, ready);
      window.removeEventListener(ACCOUNT_CANCELLED, cancel);
      resolve(allowed);
    };
    const ready = () => finish(true);
    const cancel = () => finish(false);
    window.addEventListener(ACCOUNT_READY, ready, { once: true });
    window.addEventListener(ACCOUNT_CANCELLED, cancel, { once: true });
    signal.addEventListener("abort", cancel, { once: true });
    requestAccount(true);
  });
}

/**
 * Source d'étapes côté navigateur : appelle /api/tutor et lit le flux NDJSON.
 * Chaque ligne est revalidée ici aussi (défense en profondeur).
 */
import { StreamEvent } from "@/domain/scene/schema";
import { readLines } from "@/domain/tutor/ndjson";
import type { TutorSource } from "@/engine/ports";
import { sessionHeaders } from "@/services/session";
import { updateTrialFromResponse, waitForAccount } from "@/services/trialEvents";

export function createHttpSource(endpoint = "/api/tutor"): TutorSource {
  return {
    async *open(request, signal) {
      const fetchTurn = () => fetch(endpoint, {
        method: "POST",
        signal,
        headers: { "Content-Type": "application/json", ...sessionHeaders() },
        body: JSON.stringify(request),
      });
      let response: Response;
      try {
        response = await fetchTurn();
        updateTrialFromResponse(response);
        if (response.status === 401 && response.headers.get("X-Nesalio-Account-Required") === "1") {
          await response.body?.cancel();
          if (!(await waitForAccount(signal))) return;
          response = await fetchTurn();
          updateTrialFromResponse(response);
        }
      } catch {
        if (signal.aborted) return;
        yield { kind: "error", code: "upstream", message: "Impossible de joindre Nesa. Vérifie ta connexion." };
        return;
      }

      if (!response.body) {
        yield { kind: "error", code: "upstream", message: "Réponse vide du serveur." };
        return;
      }

      for await (const line of readLines(response.body)) {
        let json: unknown;
        try {
          json = JSON.parse(line);
        } catch {
          continue;
        }
        const parsed = StreamEvent.safeParse(json);
        if (parsed.success) yield parsed.data;
      }
    },
  };
}

